{
  "schema": "tlalpowa.atmosfera_cache_analitico.v2",
  "purpose": "Define reglas de cache transitorio: está prohibido persistir resúmenes IXIPTLAH; las gráficas consumen muestras directas día/hora/minuto.",
  "current_enabled_products": [
    {
      "factor_id": "o3",
      "source_family": "RAMA CSV horario",
      "spatial_method": "rama_hourly_station_area_triangulated_v2",
      "temporal_base": "horario_a_diario_y_semana_epidemiologica",
      "spatial_unit": "alcaldia_municipio",
      "cache_file": "Datos/Atmosfera/cache_analitico/o3_alcaldia_diario_triangulado_{decada}.tsv",
      "validation": "La firma de cohorte usa archivos RAMA por anio, geometria de estaciones y geometria territorial; cada celda diaria proviene de triangulacion horaria con estaciones O3 validas, muestreo dentro del poligono de la alcaldia/municipio y agregacion diaria antes de compararse por semana epidemiologica."
    }
  ],
  "future_reserved_products": [
    {
      "factor_id": "sentinel_5p_o3",
      "status": "reservado_no_aplicado",
      "expected_spatial_unit": "alcaldia_municipio",
      "expected_temporal_base": "diario_o_subdiario",
      "notes": "Puede incorporarse como nuevo metodo/firma sin sustituir el cache RAMA existente."
    },
    {
      "factor_id": "nubosidad_satelital",
      "status": "reservado_no_aplicado",
      "expected_spatial_unit": "alcaldia_municipio",
      "expected_temporal_base": "horario_o_diario",
      "notes": "Debe agregarse como factor independiente para permitir graficas multivariables sin invalidar O3."
    },
    {
      "factor_id": "otros_contaminantes",
      "status": "reservado_no_aplicado",
      "expected_spatial_unit": "alcaldia_municipio",
      "expected_temporal_base": "horario_diario_semanal",
      "notes": "La clave de cache debe incluir factor, metodo espacial, firma de fuente y firma geometrica."
    }
  ],
  "non_regression_rules": [
    "Ninguna capa futura debe borrar ni reinterpretar un cache previo: debe generar una firma nueva.",
    "La UI debe preferir lecturas cacheadas y solo calcular celdas faltantes o con firma de cohorte nueva.",
    "Los productos atmosfericos agregados deben permanecer en Datos para exportacion y reutilizacion de graficas.",
    "Los caches externos no son IXIPTLAH y no deben sustituir muestras directas; ningún IXIPTLAH elemental debe llenarse con basura o agregados."
  ],
  "ixiptlah_sm_v56": {
    "contrato": "un .ixiptlah por elemento del catálogo, sin subcarpetas y sin nuevos tipos externos de archivo",
    "prohibicion_resumenes": "prohibido persistir resumen mensual, diario, horario, catálogo agregado o cualquier vista preagregada",
    "graficas": "las gráficas consumen muestras directas día/hora/minuto; las uniones son transitorias al seleccionar casillas",
    "secundarios": "sólo secundarios físicos/químicos defendibles desde primarios simultáneos y unidades compatibles"
  }
}

{
  "schema_version": "1.0",
  "description": "Contrato local para integrar datos atmosfericos horarios o diarios a Tlalpowa.",
  "jsonl_record": {
    "datetime_local": "YYYY-MM-DDTHH:mm:ss",
    "station_id": "codigo_estacion",
    "station_name": "nombre_estacion",
    "parameter_id": "o3|pm10|pm25|co|no2|so2|no|nox|pmco|tmp|rh|wsp|wdr|gr|uva|uvb",
    "parameter_kind": "contaminante|meteorologico",
    "value": 0.0,
    "unit": "ppb|ppm|ug/m3",
    "quality": "valid|estimated|missing",
    "source": "aire.cdmx.gob.mx"
  },
  "planned_outputs": {
    "jsonl": "web/data/atmosfera.jsonl",
    "pollutants": "web/data/contaminantes.json",
    "cloud_reconstruction": "web/data/nube_contaminantes.json"
  }
}

{
  "version": "2026-05-25.2",
  "purpose": "Politica visual para estaciones RAMA/SIMAT: pin central solido por categoria y halo translucido por semaforo de concentracion o magnitud meteorologica. El halo es representatividad cartografica conservadora, no interpolacion causal ni radio fisico del sensor.",
  "spatial_scale_basis": {
    "source": "40 CFR Part 58 Appendix D / EPA ambient air monitoring spatial scales",
    "scales_m": {
      "micro": "0-100 m",
      "middle": "100-500 m",
      "neighborhood": "500-4000 m",
      "urban": "4000-50000 m"
    }
  },
  "health_color_basis": {
    "source": "NOM-172-SEMARNAT-2023",
    "note": "Para PM10, PM2.5, O3, CO, NO2 y SO2 se codifica el halo con bandas semaforicas compatibles con el indice Aire y Salud. O3/NO2/SO2 se convierten de ppm a ppb cuando la unidad lo indica; PM en mg/m3 se convierte a ug/m3 cuando aplica. NO y NOx usan NO2 solo como intensidad visual conservadora, no dictamen normativo."
  },
  "render_contract": {
    "pin_center": "circulo solido, sin borde, color fijo de la categoria",
    "halo": "un solo circulo relleno translucido, sin borde, color del semaforo de la medicion",
    "draw_order": "primero halos, despues centros solidos; evita anillos concentricos y reduce parpadeo",
    "ixiptlah_fast_path": "prohibido escribir AtmosphereRenderSummary; mapa y gráficas leen muestras directas día/hora/minuto del .ixiptlah elemental seleccionado"
  },
  "radii_m": {
    "O3": {
      "radius_m": 8500,
      "scale": "urban",
      "reason": "contaminante secundario regional; representatividad urbana conservadora"
    },
    "PM2.5": {
      "radius_m": 4000,
      "scale": "neighborhood/urban-low",
      "reason": "fraccion fina con mayor persistencia espacial que PM10"
    },
    "PM10": {
      "radius_m": 2500,
      "scale": "neighborhood",
      "reason": "fraccion gruesa mas influida por fuentes locales y resuspension"
    },
    "CO": {
      "radius_m": 500,
      "scale": "middle",
      "reason": "primario de trafico/combustion con gradientes locales"
    },
    "NO_NO2_NOx": {
      "radius_m": 650,
      "scale": "middle",
      "reason": "oxidos de nitrogeno reactivos y cercanos a fuentes"
    },
    "SO2": {
      "radius_m": 1200,
      "scale": "middle/neighborhood",
      "reason": "fuentes puntuales o corredores de emision; radio local conservador"
    },
    "temperatura_humedad": {
      "radius_m": 2200,
      "scale": "urban microclimate",
      "reason": "microclima urbano condicionado por suelo, altitud y cobertura"
    },
    "viento": {
      "radius_m": 5000,
      "scale": "urban mixed layer",
      "reason": "variable direccional con coherencia urbana mayor, modulada por orografia"
    },
    "radiacion": {
      "radius_m": 4500,
      "scale": "urban radiative field",
      "reason": "campo radiativo relativamente continuo salvo nubosidad/local shading"
    }
  },
  "performance": {
    "default_map_load": "solo muestras directas día/hora/minuto del .ixiptlah elemental seleccionado",
    "raw_ixiptlah_to_map": "activar con TLALPOWA_ATMOS_RAW_IXIPTLAH_TO_MAP=1 si se desea pintar mediciones crudas; no recomendado para navegacion fluida",
    "raw_ixiptlah_write": "activar con TLALPOWA_ATMOS_RAW_IXIPTLAH=1 si se desea persistir cada medicion horaria sin escribir resúmenes de render"
  },
  "ixiptlah_fast_path": "sin resumen persistente: el mapa lee muestras directas día/hora/minuto del .ixiptlah elemental seleccionado; cualquier agrupación visual es transitoria",
  "pin_template": "círculo sólido con contorno sólido delgado; sin degradés internos, externos, halos ni sombras"
}

